try {
  let inputItem = {};
  try {
    inputItem = $input.item.json;
  } catch (e) {}

  let extraireData = {};
  try {
    const extraireItems = $('Extraire message1').all();
    if (extraireItems && extraireItems.length > 0) extraireData = extraireItems[0].json;
  } catch (e) {}

  let whatsappData = {};
  try {
    const items = $('WhatsApp Trigger1').all();
    if (items && items.length > 0) whatsappData = items[0].json;
  } catch (e) {}

  const waMessage =
    whatsappData?.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]
    || whatsappData?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]
    || {};

  const telephone = extraireData.telephone || inputItem.telephone || inputItem.from || waMessage.from || '';
  const message_texte = extraireData.message_texte || inputItem.message_texte || inputItem.message || inputItem.text || waMessage.text?.body || '';

  const maintenant = new Date().toISOString();
  const NUMERO_CONTACT_GENERAL = "33781635224";

  function premiereValeur(champ) {
    return Array.isArray(champ) ? champ[0] : champ;
  }

  let enrichies = [];
  try {
    enrichies = $('Chercher réservation1').all().map(i => {
      const r = i.json;
      const debut = r.Date_Debut ? new Date(r.Date_Debut) : null;
      const fin = r.Date_Fin ? new Date(r.Date_Fin) : null;
      const aujourdhui = new Date();

      let statut = 'INCONNU';
      if (debut && fin) {
        if (aujourdhui >= debut && aujourdhui <= fin) statut = 'EN_COURS';
        else if (aujourdhui < debut) statut = 'PROCHAIN';
        else if (aujourdhui > fin) statut = 'PASSE';
      }

      return {
        ...r,
        _statut: statut,
        _arrivee: debut ? debut.getTime() : 0,
        _depart: fin ? fin.getTime() : 0
      };
    });
  } catch (e) {}

  const enCours = enrichies.find(r => r._statut === 'EN_COURS');
  const prochaines = enrichies.filter(r => r._statut === 'PROCHAIN').sort((a, b) => a._arrivee - b._arrivee);
  const passees = enrichies.filter(r => r._statut === 'PASSE').sort((a, b) => b._depart - a._depart);

  const choisie = enCours || prochaines[0] || passees[0];
  let statut = choisie ? choisie._statut : 'INCONNU';

  let reservation = null;
  if (choisie) {
    const numeroProprietaireLogement =
      premiereValeur(choisie.Numero_Proprietaire) ||
      premiereValeur(choisie.Numero_Proprietaire_Defaut) ||
      premiereValeur(choisie.telephone_voyageur) ||
      NUMERO_CONTACT_GENERAL;

    const idLogement =
      premiereValeur(choisie['nom du logement']) ||
      premiereValeur(choisie.Nom_Logement) ||
      premiereValeur(choisie.nom_logement) ||
      premiereValeur(choisie.id_logement) ||
      '';

    reservation = {
      id_logement: idLogement,
      cle_unique: premiereValeur(choisie.Cle_Unique) || '',
      code_conv: premiereValeur(choisie.Code_conv) || premiereValeur(choisie.code_conv) || '',
      nom_voyageur: choisie.Nom_Voyageur || '',
      telephone_voyageur: premiereValeur(choisie.telephone_voyageur) || '',
      date_arrivee: choisie.Date_Debut || '',
      date_depart: choisie.Date_Fin || '',
      logement: idLogement,
      conciergerie: premiereValeur(choisie.Nom_Conciergerie) || '',
      adresse: premiereValeur(choisie.adresse) || '',
      ville: premiereValeur(choisie.ville) || premiereValeur(choisie.Ville) || '',
      wifi_nom: premiereValeur(choisie.Wifi_Nom) || '',
      wifi_mdp: premiereValeur(choisie.wifi_code) || '',
      code_acces: premiereValeur(choisie.Code_Acces) || '',
      heure_checkin: premiereValeur(choisie.checkin) || '',
      heure_checkout: premiereValeur(choisie.checkout) || '',
      parking: premiereValeur(choisie.parking) || '',
      consignes_arrivee: premiereValeur(choisie.Consignes_Arrivee) || '',
      consignes_depart: premiereValeur(choisie.regle) || '',
      numero_proprietaire: numeroProprietaireLogement
    };
  }

  const numeroProprietaireFinal = reservation ? reservation.numero_proprietaire : NUMERO_CONTACT_GENERAL;

  // Lien d'affiliation GetYourGuide, construit à partir de la ville du
  // logement déjà résolue dans `reservation`. Vide si aucune réservation
  // ou aucune ville renseignée dans Airtable.
  const PARTNER_ID_GETYOURGUIDE = 'BCNQE2V';
  let lienActivites = '';
  if (reservation && reservation.ville) {
    const villeEncodee = encodeURIComponent(reservation.ville);
    lienActivites = `https://www.getyourguide.fr/s/?q=${villeEncodee}&partner_id=${PARTNER_ID_GETYOURGUIDE}&cmp=share_to_earn`;
  }

  let contexteReservation;
  if (reservation) {
    contexteReservation = [
      `- Conciergerie : ${reservation.conciergerie}`,
      `- Logement : ${reservation.logement}`,
      `- Adresse : ${reservation.adresse}`,
      `- Ville : ${reservation.ville}`,
      `- Parking : ${reservation.parking}`,
      `- Téléphone voyageur : ${reservation.telephone_voyageur}`,
      `- Dates du séjour : du ${reservation.date_arrivee} au ${reservation.date_depart}`,
      `- Heure de check-in : ${reservation.heure_checkin}`,
      `- Heure de check-out : ${reservation.heure_checkout}`,
      `- Wi-Fi : réseau "${reservation.wifi_nom}" / mot de passe "${reservation.wifi_mdp}"`,
      `- Code d'accès : ${reservation.code_acces}`,
      `- Code de conversation : ${reservation.code_conv}`,
      `- Consignes arrivée : ${reservation.consignes_arrivee}`,
      `- Consignes départ (règles) : ${reservation.consignes_depart}`,
      lienActivites ? `- Lien activités locales (à proposer si pertinent) : ${lienActivites}` : ''
    ].filter(Boolean).join('\n');
  } else {
    contexteReservation = '- Aucune réservation trouvée pour ce numéro : tu ne connais ni logement ni conciergerie.';
  }

  const ownerAlertPrefix = reservation
    ? `Conciergerie : ${reservation.conciergerie}\nLogement : ${reservation.logement}`
    : 'Conciergerie : Inconnue\nLogement : Inconnu';

  return [{
    json: {
      telephone,
      message_texte,
      maintenant,
      statut,
      reservation,
      numero_proprietaire: numeroProprietaireFinal,
      contexte_reservation: contexteReservation,
      owner_alert_prefix: ownerAlertPrefix,
      lien_activites: lienActivites
    }
  }];
} catch (err) {
  return [{
    json: {
      erreur: true,
      message_erreur: err.message,
      stack: err.stack
    }
  }];
}

