const logementId = $input.item.json.id;

const reservations = [];

if (icsData) {
    const eventRegex = /BEGIN:VEVENT([\s\S]*?)END:VEVENT/g;
    let match;

    while ((match = eventRegex.exec(icsData)) !== null) {
        const eventText = match[1];
        const startMatch = eventText.match(/DTSTART(?:;[^:]*)?:([0-9TZ]+)/);
        const endMatch = eventText.match(/DTEND(?:;[^:]*)?:([0-9TZ]+)/);
        const summaryMatch = eventText.match(/SUMMARY:(.*)/);

        if (startMatch && endMatch) {
            const dateDebutFormatee = formatIcsDate(startMatch[1]);
            const dateFinFormatee = formatIcsDate(endMatch[1]);
            const titreReservation = summaryMatch ? summaryMatch[1].trim() : "Réservé";
            const cleGeneree = nomLogement + "_" + titreReservation + "_" + dateDebutFormatee;

            reservations.push({
                json: {
                    logement: nomLogement,
                    Cle_Unique: cleGeneree,
                    date_debut: dateDebutFormatee,
                    date_fin: dateFinFormatee,
                    titre: titreReservation,
                    // On envoie directement l'ID Airtable dans un tableau pour la relation
                    Logement_Relation: logementId ? [logementId] : [] 
                }
            });
        }
    }
}

function formatIcsDate(icsDateStr) {
    const year = icsDateStr.substr(0, 4);
    const month = icsDateStr.substr(4, 2);
    const day = icsDateStr.substr(6, 2);
    return `${year}-${month}-${day}`;
}

return reservations;

