const cleUnique = body.cle_unique || "";

return [{ json: { formula: `{Cle_Unique}='${cleUnique.replace(/'/g, "\\'")}'` } }];

const record = $input.first().json;

const chars = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"; // sans 0/O/1/I pour éviter les confusions
let code = "";
for (let i = 0; i < 5; i++) {
  code += chars[Math.floor(Math.random() * chars.length)];
}

return [{ json: { record_id: record.id, code_conv: code } }];

