const idLogements = $('get-messages').first().json.body.id_logements || [];

if (idLogements.length === 0) {
  return [{ json: { formula: "FALSE()" } }];
}

const clauses = idLogements.map(
  (id) => `{id_logement}='${id.replace(/'/g, "\\'")}'`
);

return [{ json: { formula: `OR(${clauses.join(",")})` } }];

